    INSERT INTO "Question" ("id", "assessmentId", "textEn", "textFr", "order", "points", "setNumber") VALUES
      ('b1663be5-de73-40b0-841b-e3cc27996a0f', a_id, $bp$What does the Series Foreword say about a wealthy man, to explain the purpose of the series?$bp$, $bp$Que dit l'Avant-propos de la série au sujet d'un homme riche, pour expliquer le but de la série ?$bp$, 0, 1, 3),
      ('f28e5fd3-92ed-45df-9871-a77a77973b8a', a_id, $bp$According to the Introduction, what does Romans 5:17 teach about reigning in life?$bp$, $bp$Selon l'Introduction, qu'enseigne Romains 5.17 sur le fait de régner dans la vie ?$bp$, 1, 1, 3),
      ('9f0d2835-4fc6-470c-bd0c-19d6a0acdd79', a_id, $bp$What does Chapter One say about the tense of Ephesians 1:3, "has blessed us"?$bp$, $bp$Que dit le chapitre un du temps du verbe en Éphésiens 1.3, « nous a bénis » ?$bp$, 2, 1, 3),
      ('1ed622e2-ac44-4c80-93e1-c1d99216c45d', a_id, $bp$Why does James 1:22 use the word "deceiving," according to the book?$bp$, $bp$Pourquoi Jacques 1.22 emploie-t-il le mot « trompant », selon le livre ?$bp$, 3, 1, 3),
      ('14ba6859-4991-46e2-9fed-b34779d4b23f', a_id, $bp$In the activation steps of Chapter One, what is the lock and what is the key?$bp$, $bp$Dans les étapes d'activation du chapitre un, quelle est la serrure et quelle est la clé ?$bp$, 4, 1, 3),
      ('dac1cc5d-3dbf-4448-bee5-b17aa24ba9e3', a_id, $bp$What does the book call passive waiting for circumstances to change?$bp$, $bp$Comment le livre appelle-t-il l'attente passive d'un changement des circonstances ?$bp$, 5, 1, 3),
      ('7f451f69-58ee-413f-941f-d937d430895a', a_id, $bp$According to Chapter Two, what is the difference between your position in Christ and your experience of it?$bp$, $bp$Selon le chapitre deux, quelle est la différence entre votre position en Christ et votre expérience de celle-ci ?$bp$, 6, 1, 3),
      ('a02eb6fe-12a1-453b-b67a-8251b1622a46', a_id, $bp$What does the book say about the enemy after the Cross, based on Colossians 2:15?$bp$, $bp$Que dit le livre de l'ennemi après la Croix, d'après Colossiens 2.15 ?$bp$, 7, 1, 3),
      ('f73ea20b-b523-4c3f-a0d7-7880459570b8', a_id, $bp$What did Mephibosheth call himself when he was brought before David?$bp$, $bp$Comment Mephibosheth s'est-il appelé lui-même quand il a été amené devant David ?$bp$, 8, 1, 3),
      ('46333192-5ab0-45b2-bf65-798298693003', a_id, $bp$Which three dimensions does the book give for the key of knowledge?$bp$, $bp$Quelles trois dimensions le livre donne-t-il pour la clé de la connaissance ?$bp$, 9, 1, 3),
      ('8627ab92-b6b4-4d0b-8c2a-e90c29cc6177', a_id, $bp$What did Jesus say about the lawyers in Luke 11:52, according to the book?$bp$, $bp$Selon le livre, qu'a dit Jésus des docteurs de la loi en Luc 11.52 ?$bp$, 10, 1, 3),
      ('b3107296-4d1a-4bee-9f05-a55dfcee274a', a_id, $bp$What does Chapter Four say about the law of the spoken word?$bp$, $bp$Que dit le chapitre quatre de la loi de la parole prononcée ?$bp$, 11, 1, 3),
      ('5561d929-d22e-428e-9af2-286111137bd9', a_id, $bp$How does the book show that prayer is "the protocol of the powerful"?$bp$, $bp$Comment le livre montre-t-il que la prière est « le protocole des puissants » ?$bp$, 12, 1, 3),
      ('ee4625e8-52c5-4857-84f8-a5e89039d26d', a_id, $bp$What shift does the key of understanding Kingdom systems produce, according to the book?$bp$, $bp$Quel changement la clé de la compréhension des systèmes du Royaume produit-elle, selon le livre ?$bp$, 13, 1, 3),
      ('00f19676-001b-4f68-abac-17378e55b8a6', a_id, $bp$What does the book note about when Jesus gave the keys of the Kingdom to His disciples?$bp$, $bp$Que note le livre sur le moment où Jésus a donné les clés du Royaume à ses disciples ?$bp$, 14, 1, 3),
      ('c3281dca-e2d9-4955-95db-97d1614860c3', a_id, $bp$What did Elisha do whenever a crisis came, according to the book?$bp$, $bp$Que faisait Élisée chaque fois qu'une crise survenait, selon le livre ?$bp$, 15, 1, 3),
      ('3b80ec48-5303-42da-80bf-7f2cbb5d0256', a_id, $bp$What does the Key Insight in Chapter Five say about the fifty-three keys?$bp$, $bp$Que dit l'Idée clé du chapitre cinq au sujet des cinquante-trois clés ?$bp$, 16, 1, 3),
      ('416ed4c7-1385-4b6f-bff0-3a9d1597f342', a_id, $bp$What does the book say about Nicodemus in John 3:3, "cannot see the kingdom"?$bp$, $bp$Que dit le livre de Nicodème en Jean 3.3, « ne peut voir le royaume » ?$bp$, 17, 1, 3),
      ('38195a03-948f-4716-94c0-a8e4b0487abf', a_id, $bp$Which of these is one of the five changes that the new birth brings, according to Chapter Six?$bp$, $bp$Lequel de ces éléments est l'un des cinq changements qu'apporte la nouvelle naissance, selon le chapitre six ?$bp$, 18, 1, 3),
      ('a2c9f3f9-82f9-4777-b548-858918879432', a_id, $bp$What makes a born-again believer's identity "immune to circumstantial attack"?$bp$, $bp$Qu'est-ce qui rend l'identité d'un croyant né de nouveau « immunisée contre les attaques circonstancielles » ?$bp$, 19, 1, 3),
      ('97163d8a-22fc-48b8-aaa6-fd78b2e9e26a', a_id, $bp$The book teaches that the Kingdom of God is governed by laws, not a random collection of miracles.$bp$, $bp$Le livre enseigne que le Royaume de Dieu est gouverné par des lois, et non par une collection aléatoire de miracles.$bp$, 20, 1, 3),
      ('d122187e-71fe-40b2-8fe0-363165b1513e', a_id, $bp$The book teaches that the main targets of 2 Corinthians 10:4-5 are demons rather than wrong thought systems.$bp$, $bp$Le livre enseigne que les cibles principales de 2 Corinthiens 10.4-5 sont des démons plutôt que des systèmes de pensée erronés.$bp$, 21, 1, 3),
      ('cbefbe64-ae45-4469-a607-2e6c508973a8', a_id, $bp$The book says Joseph's engagement with Kingdom systems produced results even in prison.$bp$, $bp$Le livre dit que l'engagement de Joseph avec les systèmes du Royaume a produit des résultats même en prison.$bp$, 22, 1, 3),
      ('7f5400a4-07e9-40ea-9355-4cfff9cf607b', a_id, $bp$The book says Moses knew the ways of God, while Israel saw only His acts.$bp$, $bp$Le livre dit que Moïse connaissait les voies de Dieu, tandis qu'Israël ne voyait que ses actes.$bp$, 23, 1, 3),
      ('18575748-ab91-4210-a38c-f4935c2ab33d', a_id, $bp$The book says the sons of Sceva failed because they did not know the right words to say.$bp$, $bp$Le livre dit que les fils de Scéva ont échoué parce qu'ils ne connaissaient pas les bonnes paroles à prononcer.$bp$, 24, 1, 3);
    INSERT INTO "Option" ("id", "questionId", "textEn", "textFr", "isCorrect", "order") VALUES
      ('17f70f4f-3d1d-4f49-9051-2092954d0b6f', 'b1663be5-de73-40b0-841b-e3cc27996a0f', $bp$He does not labour to become rich again; he learns to access and use the wealth he has$bp$, $bp$Il ne travaille pas pour redevenir riche ; il apprend à accéder à la richesse qu'il a et à s'en servir$bp$, TRUE, 0),
      ('5ace7e95-f379-41bf-8378-00901014b9af', 'b1663be5-de73-40b0-841b-e3cc27996a0f', $bp$He must keep working hard, or his wealth will slowly leave him and his whole family$bp$, $bp$Il doit continuer à travailler dur, sinon sa richesse le quittera peu à peu, lui et toute sa famille$bp$, FALSE, 1),
      ('d281e14b-5062-4a0f-8878-d8a3e038cf8d', 'b1663be5-de73-40b0-841b-e3cc27996a0f', $bp$He should give his wealth away first, so that God can return it to him again later$bp$, $bp$Il doit d'abord donner sa richesse, afin que Dieu puisse la lui rendre plus tard$bp$, FALSE, 2),
      ('0629d828-2c55-4227-907b-0f365489f9d4', 'b1663be5-de73-40b0-841b-e3cc27996a0f', $bp$He cannot enjoy his wealth until he has finished paying every debt that he owes$bp$, $bp$Il ne peut pas jouir de sa richesse avant d'avoir fini de payer toutes ses dettes$bp$, FALSE, 3),
      ('19db2d06-569d-4ce7-b59e-5733dd089d08', 'f28e5fd3-92ed-45df-9871-a77a77973b8a', $bp$It is selective; it comes to church leaders, because they hold the keys for others$bp$, $bp$C'est sélectif ; cela vient aux dirigeants d'église, parce qu'ils détiennent les clés pour les autres$bp$, FALSE, 0),
      ('fd0c289f-626b-4a21-843e-f11f8191bbf4', 'f28e5fd3-92ed-45df-9871-a77a77973b8a', $bp$It is delayed; it comes to believers only after death, when they enter Heaven$bp$, $bp$C'est différé ; cela ne vient aux croyants qu'après la mort, quand ils entrent au Ciel$bp$, FALSE, 1),
      ('aaf20f52-064e-40c0-a9fd-fc7e05667149', 'f28e5fd3-92ed-45df-9871-a77a77973b8a', $bp$It is not automatic; it comes from actively receiving what grace has provided$bp$, $bp$Ce n'est pas automatique ; cela vient du fait de recevoir activement ce que la grâce a fourni$bp$, TRUE, 2),
      ('55f301a7-7e19-45f6-97e1-7b333f95a747', 'f28e5fd3-92ed-45df-9871-a77a77973b8a', $bp$It is automatic; it comes to every believer the day he is born again, with no effort$bp$, $bp$C'est automatique ; cela vient à chaque croyant le jour où il naît de nouveau, sans aucun effort$bp$, FALSE, 3),
      ('13d53007-033f-4702-9f60-9d546e0af246', '9f0d2835-4fc6-470c-bd0c-19d6a0acdd79', $bp$It is future tense and promised action: the transaction will be done when the believer is ready$bp$, $bp$C'est le futur et une action promise : la transaction sera faite quand le croyant sera prêt$bp$, FALSE, 0),
      ('4630699d-b007-47d1-933d-2f5227bdd97f', '9f0d2835-4fc6-470c-bd0c-19d6a0acdd79', $bp$It is partial tense and seasonal action: the transaction is done only in some seasons$bp$, $bp$C'est un temps partiel et une action saisonnière : la transaction n'est faite qu'en certaines saisons$bp$, FALSE, 1),
      ('f62a71c2-4d67-461f-a5d7-04abd07db4a7', '9f0d2835-4fc6-470c-bd0c-19d6a0acdd79', $bp$It is present tense and ongoing action: the transaction is done again each time one prays$bp$, $bp$C'est le présent et une action continue : la transaction est refaite chaque fois qu'on prie$bp$, FALSE, 2),
      ('9496a018-0e03-4b1d-87da-13d7470cbcb2', '9f0d2835-4fc6-470c-bd0c-19d6a0acdd79', $bp$It is past tense and completed action: the transaction is done and he is already rich$bp$, $bp$C'est le passé et une action achevée : la transaction est faite et il est déjà riche$bp$, TRUE, 3),
      ('14bcd661-fe79-443c-8469-11f9e58a2f61', '1ed622e2-ac44-4c80-93e1-c1d99216c45d', $bp$A person who reads the Word in private is deceived about what leaders teach$bp$, $bp$Une personne qui lit la Parole en privé est trompée sur ce que les dirigeants enseignent$bp$, FALSE, 0),
      ('d8628b4b-51ba-4e26-aef1-da3eb961943e', '1ed622e2-ac44-4c80-93e1-c1d99216c45d', $bp$A person who applies the Word without hearing it first is easily deceived by others$bp$, $bp$Une personne qui applique la Parole sans l'avoir d'abord entendue est facilement trompée par les autres$bp$, FALSE, 1),
      ('e65734fb-3d39-46ff-9639-0b9363facf34', '1ed622e2-ac44-4c80-93e1-c1d99216c45d', $bp$A person who hears but does not apply the Word is in a state of self-deception$bp$, $bp$Une personne qui entend la Parole sans l'appliquer est dans un état d'auto-tromperie$bp$, TRUE, 2),
      ('7774de5b-d5a9-447a-bab6-ec64f4060fcf', '1ed622e2-ac44-4c80-93e1-c1d99216c45d', $bp$A person who hears the Word only once is deceived by the enemy about its meaning$bp$, $bp$Une personne qui n'entend la Parole qu'une seule fois est trompée par l'ennemi sur son sens$bp$, FALSE, 3),
      ('fb425f12-751c-4665-943f-2c8c37d6d25b', '14ba6859-4991-46e2-9fed-b34779d4b23f', $bp$Your circumstance is the lock; the amount of your giving is the key to it$bp$, $bp$Votre circonstance est la serrure ; le montant de votre don en est la clé$bp$, FALSE, 0),
      ('dcee3a3e-7610-46f9-989e-fd2f117f1d43', '14ba6859-4991-46e2-9fed-b34779d4b23f', $bp$Your hidden sin is the lock; the confession of every wrong is the key to it$bp$, $bp$Votre péché caché est la serrure ; la confession de chaque tort en est la clé$bp$, FALSE, 1),
      ('08331b0e-2657-4b33-8ade-9f6ba7532170', '14ba6859-4991-46e2-9fed-b34779d4b23f', $bp$The devil himself is the lock; a loud and angry prayer is the key to it$bp$, $bp$Le diable lui-même est la serrure ; une prière forte et colérique en est la clé$bp$, FALSE, 2),
      ('f5ea4437-606d-4964-827c-edb7540c5bc2', '14ba6859-4991-46e2-9fed-b34779d4b23f', $bp$The lie that accepts your lack as permanent is the lock; the truth is the key$bp$, $bp$Le mensonge qui accepte votre manque comme permanent est la serrure ; la vérité en est la clé$bp$, TRUE, 3),
      ('10979732-3228-49c0-89e5-fd86b689e3db', 'dac1cc5d-3dbf-4448-bee5-b17aa24ba9e3', $bp$Rest rather than work, since a resting believer has stopped all of his striving$bp$, $bp$Du repos plutôt que du travail, puisqu'un croyant qui se repose a cessé tous ses efforts$bp$, FALSE, 0),
      ('1d553a1c-9087-49c0-a76c-1bb1c6da4fcc', 'dac1cc5d-3dbf-4448-bee5-b17aa24ba9e3', $bp$Presumption rather than faith, since true faith is active and engages Kingdom Keys$bp$, $bp$De la présomption plutôt que de la foi, puisque la vraie foi est active et engage les clés du Royaume$bp$, TRUE, 1),
      ('4664e684-0765-43d0-a2da-0c346a50536f', 'dac1cc5d-3dbf-4448-bee5-b17aa24ba9e3', $bp$Patience rather than doubt, since a patient believer lets God choose the moment$bp$, $bp$De la patience plutôt que du doute, puisqu'un croyant patient laisse Dieu choisir le moment$bp$, FALSE, 2),
      ('139c437b-0e3f-405c-be78-ec1e5ab08292', 'dac1cc5d-3dbf-4448-bee5-b17aa24ba9e3', $bp$Humility rather than pride, since a humble believer leaves everything to God alone$bp$, $bp$De l'humilité plutôt que de l'orgueil, puisqu'un croyant humble laisse tout à Dieu seul$bp$, FALSE, 3),
      ('ac0cd8f1-5713-459d-ad5d-cbc881494aab', '7f451f69-58ee-413f-941f-d937d430895a', $bp$Position is fixed and complete; experience is progressive and needs your active part$bp$, $bp$La position est fixe et complète ; l'expérience est progressive et demande votre part active$bp$, TRUE, 0),
      ('d6d91692-42b9-4666-955d-36a2c6fea8c2', '7f451f69-58ee-413f-941f-d937d430895a', $bp$Position is gradual and earned; experience is fixed and complete from the very first day$bp$, $bp$La position est graduelle et gagnée ; l'expérience est fixe et complète dès le premier jour$bp$, FALSE, 1),
      ('d0ed3c7e-ffa4-49a1-8f75-b8ffcd320d02', '7f451f69-58ee-413f-941f-d937d430895a', $bp$Position is lost through sin; experience is restored through repentance and good works$bp$, $bp$La position se perd par le péché ; l'expérience se rétablit par la repentance et les bonnes œuvres$bp$, FALSE, 2),
      ('8c587440-31b9-423a-961f-60b111ca6578', '7f451f69-58ee-413f-941f-d937d430895a', $bp$Position is private and hidden; experience is public and seen by every person around you$bp$, $bp$La position est privée et cachée ; l'expérience est publique et vue de tous ceux qui vous entourent$bp$, FALSE, 3),
      ('fe910cf5-2c68-413e-8b01-cae7e6b6b328', 'a02eb6fe-12a1-453b-b67a-8251b1622a46', $bp$He was destroyed completely, so he no longer has any influence in the world at all today$bp$, $bp$Il a été complètement détruit, et n'a donc plus aucune influence dans le monde aujourd'hui$bp$, FALSE, 0),
      ('27b87888-48ad-4b68-842a-131d76b148d3', 'a02eb6fe-12a1-453b-b67a-8251b1622a46', $bp$He still operates, but his legal authority is stripped, and he counts on us not knowing$bp$, $bp$Il agit encore, mais son autorité légale est dépouillée, et il compte sur le fait que nous l'ignorons$bp$, TRUE, 1),
      ('b8a82f81-5b27-4ed6-80a2-8478fc0e43b7', 'a02eb6fe-12a1-453b-b67a-8251b1622a46', $bp$He was bound in Heaven only, and still has full legal authority in the affairs of earth$bp$, $bp$Il n'a été lié qu'au Ciel, et garde toute son autorité légale dans les affaires de la terre$bp$, FALSE, 2),
      ('248fe6fe-7924-406b-938f-9057134527cd', 'a02eb6fe-12a1-453b-b67a-8251b1622a46', $bp$He still rules the earth, but his power will be removed when believers pray enough$bp$, $bp$Il règne encore sur la terre, mais sa puissance sera retirée quand les croyants auront assez prié$bp$, FALSE, 3),
      ('0b989e88-dc70-41c1-83d6-0703bf0171f8', 'f73ea20b-b523-4c3f-a0d7-7880459570b8', $bp$A fallen prince, which showed how years of exile had made him hate the king$bp$, $bp$Un prince déchu, ce qui montrait comment des années d'exil lui avaient fait haïr le roi$bp$, FALSE, 0),
      ('f69f2d4a-cd43-4b69-bef1-75a2be1edea2', 'f73ea20b-b523-4c3f-a0d7-7880459570b8', $bp$A lame servant, which showed how years of injury had made him fear the king$bp$, $bp$Un serviteur boiteux, ce qui montrait comment des années de blessure lui avaient fait craindre le roi$bp$, FALSE, 1),
      ('9a32a3b6-69fa-4607-a36d-114460f20ca9', 'f73ea20b-b523-4c3f-a0d7-7880459570b8', $bp$A dead dog, which showed how years in Lo Debar had damaged his sense of identity$bp$, $bp$Un chien mort, ce qui montrait comment des années à Lo-Debar avaient abîmé son sens de l'identité$bp$, TRUE, 2),
      ('fc9cb730-23a4-436e-9bed-21be2033726c', 'f73ea20b-b523-4c3f-a0d7-7880459570b8', $bp$A hidden son, which showed how years of silence had made him proud before the king$bp$, $bp$Un fils caché, ce qui montrait comment des années de silence l'avaient rendu orgueilleux devant le roi$bp$, FALSE, 3),
      ('3287a57e-5a98-41f7-90a0-1687e66877dc', '46333192-5ab0-45b2-bf65-798298693003', $bp$Knowledge of the Father, of the Son, and of the full work of the Holy Spirit$bp$, $bp$La connaissance du Père, du Fils et de l'œuvre complète du Saint-Esprit$bp$, FALSE, 0),
      ('4f85c944-5397-4f19-961c-6fb426d0733a', '46333192-5ab0-45b2-bf65-798298693003', $bp$Knowledge of your identity, of your inheritance, and of the Kingdom systems$bp$, $bp$La connaissance de votre identité, de votre héritage et des systèmes du Royaume$bp$, TRUE, 1),
      ('5715c276-bbb7-47bd-b64f-79ec5004ca26', '46333192-5ab0-45b2-bf65-798298693003', $bp$Knowledge of your enemy, of his tactics, and of the way to defeat him in prayer$bp$, $bp$La connaissance de votre ennemi, de ses tactiques et de la manière de le vaincre dans la prière$bp$, FALSE, 2),
      ('2144d007-4006-42ee-bd74-52b32303b621', '46333192-5ab0-45b2-bf65-798298693003', $bp$Knowledge of the law, of the prophets, and of the history of the nation of Israel$bp$, $bp$La connaissance de la loi, des prophètes et de l'histoire de la nation d'Israël$bp$, FALSE, 3),
      ('bda2870e-ab51-4539-969f-059ac21751b1', '8627ab92-b6b4-4d0b-8c2a-e90c29cc6177', $bp$They locked the temple doors, and did not pray there themselves or let others pray$bp$, $bp$Ils ont verrouillé les portes du temple, et n'y priaient pas eux-mêmes ni ne laissaient les autres y prier$bp$, FALSE, 0),
      ('d1ec6e45-d60f-4c89-b08f-7a5cf1193a90', '8627ab92-b6b4-4d0b-8c2a-e90c29cc6177', $bp$They hid the Scriptures away, and did not read them themselves or let others read$bp$, $bp$Ils ont caché les Écritures, et ne les lisaient pas eux-mêmes ni ne laissaient les autres les lire$bp$, FALSE, 1),
      ('a29b9410-20f5-4c42-997b-5629d2980d00', '8627ab92-b6b4-4d0b-8c2a-e90c29cc6177', $bp$They stole the tithes of the poor, and did not give themselves or let others give$bp$, $bp$Ils ont volé les dîmes des pauvres, et ne donnaient pas eux-mêmes ni ne laissaient les autres donner$bp$, FALSE, 2),
      ('10f48fde-b41c-4feb-aae7-11a12fcd7f4c', '8627ab92-b6b4-4d0b-8c2a-e90c29cc6177', $bp$They took away the key of knowledge, and did not enter in themselves or let others in$bp$, $bp$Ils ont enlevé la clé de la connaissance, et ne sont pas entrés eux-mêmes ni n'ont laissé entrer les autres$bp$, TRUE, 3),
      ('443574a4-f0d5-443e-8e79-9b35c08ada04', 'b3107296-4d1a-4bee-9f05-a55dfcee274a', $bp$A ritual of prayer that works only when it is said aloud inside a church hall$bp$, $bp$Un rituel de prière qui ne fonctionne que lorsqu'il est prononcé à voix haute dans une salle d'église$bp$, FALSE, 0),
      ('2a8fec35-763b-4c05-9c8a-716be8bbb3fc', 'b3107296-4d1a-4bee-9f05-a55dfcee274a', $bp$A gift of prophecy that works only for those who are called to lead a church$bp$, $bp$Un don de prophétie qui ne fonctionne que pour ceux qui sont appelés à diriger une église$bp$, FALSE, 1),
      ('1604f3c4-a043-4799-8d99-bf7f350aeac3', 'b3107296-4d1a-4bee-9f05-a55dfcee274a', $bp$A private habit of thought that affects only the speaker's own mood and feelings$bp$, $bp$Une habitude privée de pensée qui n'affecte que l'humeur et les sentiments de celui qui parle$bp$, FALSE, 2),
      ('928ab2e7-5292-4c74-8328-b8daa72b75c2', 'b3107296-4d1a-4bee-9f05-a55dfcee274a', $bp$A creative and authoritative force that shapes reality, working for every citizen$bp$, $bp$Une force créatrice et autoritaire qui façonne la réalité, et qui agit pour chaque citoyen$bp$, TRUE, 3),
      ('b7844a2b-1de0-4350-aef6-e1a6e9a97b9d', '5561d929-d22e-428e-9af2-286111137bd9', $bp$Jesus prayed only in public, and taught His disciples to copy His words exactly$bp$, $bp$Jésus ne priait qu'en public, et a enseigné à ses disciples à copier exactement ses paroles$bp$, FALSE, 0),
      ('cc308fa4-cb08-4d97-9a5a-d6ea11292570', '5561d929-d22e-428e-9af2-286111137bd9', $bp$Jesus prayed only when He was weak, and stopped once His power had come back to Him$bp$, $bp$Jésus ne priait que lorsqu'il était faible, et a cessé une fois sa puissance revenue$bp$, FALSE, 1),
      ('c79db353-7d17-417b-aadf-20d9fdecc2cd', '5561d929-d22e-428e-9af2-286111137bd9', $bp$Jesus rose before dawn, prayed all night before decisions, and agonised in Gethsemane$bp$, $bp$Jésus se levait avant l'aube, priait toute la nuit avant les décisions, et luttait à Gethsémané$bp$, TRUE, 2),
      ('61c4a51e-99b7-459a-a6cc-7cf72a78c3d9', '5561d929-d22e-428e-9af2-286111137bd9', $bp$Jesus prayed only in the temple, and only on the Sabbath day before all the people$bp$, $bp$Jésus ne priait que dans le temple, et seulement le jour du sabbat devant tout le peuple$bp$, FALSE, 3),
      ('7bdafe41-83ef-43a4-a637-73d0e3f320ae', 'ee4625e8-52c5-4857-84f8-a5e89039d26d', $bp$From private faith to public fame: from silence to speaking before crowds$bp$, $bp$De la foi privée à la célébrité publique : du silence à la parole devant les foules$bp$, FALSE, 0),
      ('a799e8de-3704-4ebf-952f-fd585695d110', 'ee4625e8-52c5-4857-84f8-a5e89039d26d', $bp$From active effort to passive rest: from struggle to waiting on God alone$bp$, $bp$De l'effort actif au repos passif : de la lutte à l'attente de Dieu seul$bp$, FALSE, 1),
      ('762c9cdd-d10a-4103-8676-4138704cd725', 'ee4625e8-52c5-4857-84f8-a5e89039d26d', $bp$From victim mentality to dominion mentality: from reaction to strategy$bp$, $bp$De la mentalité de victime à la mentalité de domination : de la réaction à la stratégie$bp$, TRUE, 2),
      ('7a0e5e54-f24e-4f8a-b797-77b0829d0d5d', 'ee4625e8-52c5-4857-84f8-a5e89039d26d', $bp$From earthly wealth to heavenly reward: from giving away to storing up$bp$, $bp$De la richesse terrestre à la récompense céleste : du don à l'accumulation de trésors$bp$, FALSE, 3),
      ('696d57e5-7781-4acc-81c8-b71efd1eadaf', '00f19676-001b-4f68-abac-17378e55b8a6', $bp$After the resurrection, and only to the apostles who had never once failed Him in life$bp$, $bp$Après la résurrection, et seulement aux apôtres qui ne l'avaient jamais déçu de leur vie$bp$, FALSE, 0),
      ('7001cb2d-9cc0-4a8e-a41b-347922ce2bcf', '00f19676-001b-4f68-abac-17378e55b8a6', $bp$Before any miracle was done, and Peter received them though he would later deny Christ$bp$, $bp$Avant tout miracle accompli, et Pierre les a reçues bien qu'il dût plus tard renier Christ$bp$, TRUE, 1),
      ('798bedd4-3e85-4693-ac2f-e8b2e3bd25a3', '00f19676-001b-4f68-abac-17378e55b8a6', $bp$Before the Cross, and only to Peter alone, who was the only one worthy to hold them$bp$, $bp$Avant la Croix, et à Pierre seul, qui était le seul digne de les détenir$bp$, FALSE, 2),
      ('66aafd05-93f0-4f29-a2fe-91630f052f76', '00f19676-001b-4f68-abac-17378e55b8a6', $bp$After Pentecost, and only to the believers who had first spoken in other tongues$bp$, $bp$Après la Pentecôte, et seulement aux croyants qui avaient d'abord parlé en d'autres langues$bp$, FALSE, 3),
      ('61e777ab-4667-49b1-a49f-3c4de28a7868', 'c3281dca-e2d9-4955-95db-97d1614860c3', $bp$He assessed it, picked the right Kingdom Key, and applied it with calm authority$bp$, $bp$Il l'évaluait, choisissait la bonne clé du Royaume et l'appliquait avec une autorité calme$bp$, TRUE, 0),
      ('dbe3c200-35cb-46b1-9b3a-483641ee08bd', 'c3281dca-e2d9-4955-95db-97d1614860c3', $bp$He asked God for a new miracle each time, and never used the same key twice$bp$, $bp$Il demandait à Dieu un nouveau miracle chaque fois, et n'utilisait jamais deux fois la même clé$bp$, FALSE, 1),
      ('0639dc45-8c03-4f70-8d58-54aaabd48db6', 'c3281dca-e2d9-4955-95db-97d1614860c3', $bp$He called the other prophets together, and let the majority decide what to do$bp$, $bp$Il réunissait les autres prophètes et laissait la majorité décider quoi faire$bp$, FALSE, 2),
      ('624e5d19-41f1-41a3-a7bb-c54bbb273625', 'c3281dca-e2d9-4955-95db-97d1614860c3', $bp$He prayed for hours in fear, and waited to see whether God would answer at all$bp$, $bp$Il priait des heures dans la peur, et attendait de voir si Dieu répondrait seulement$bp$, FALSE, 3),
      ('42093291-4d88-41d7-b326-88371e43b36b', '3b80ec48-5303-42da-80bf-7f2cbb5d0256', $bp$You must master every one of them in order before you can claim any right at all$bp$, $bp$Vous devez toutes les maîtriser dans l'ordre avant de pouvoir revendiquer le moindre droit$bp$, FALSE, 0),
      ('32f4c8fe-9f78-4109-b913-2fa542cbe506', '3b80ec48-5303-42da-80bf-7f2cbb5d0256', $bp$You need only the keys of the last tier, since they include the keys that come first$bp$, $bp$Vous n'avez besoin que des clés du dernier niveau, puisqu'elles incluent celles qui viennent d'abord$bp$, FALSE, 1),
      ('c732ee8f-164c-4fd9-b5c8-ae337605ed37', '3b80ec48-5303-42da-80bf-7f2cbb5d0256', $bp$You should choose three favourites and ignore the rest, as they are not for you$bp$, $bp$Vous devriez choisir trois favorites et ignorer les autres, car elles ne sont pas pour vous$bp$, FALSE, 2),
      ('e58241a9-0e60-4611-b808-156b782f3337', '3b80ec48-5303-42da-80bf-7f2cbb5d0256', $bp$You do not need all of them to begin; start with the keys that fit your circumstances$bp$, $bp$Vous n'avez pas besoin de toutes pour commencer ; commencez par les clés qui correspondent à vos circonstances$bp$, TRUE, 3),
      ('aaa01d68-ebcb-4b0a-9d55-8726c2afc4f8', '416ed4c7-1385-4b6f-bff0-3a9d1597f342', $bp$With all his learning and discipline, he could see the Kingdom, but could not yet live in it$bp$, $bp$Avec toute son instruction et sa discipline, il pouvait voir le Royaume, mais pas encore y vivre$bp$, FALSE, 0),
      ('e38c7c0a-ecc0-458e-9d48-564a841a61c0', '416ed4c7-1385-4b6f-bff0-3a9d1597f342', $bp$With all his learning and discipline, he needed only to be reformed, and then he could enter$bp$, $bp$Avec toute son instruction et sa discipline, il avait seulement besoin d'être réformé, et alors il pouvait entrer$bp$, FALSE, 1),
      ('077574b7-ae44-4a29-92f7-5f05659150f8', '416ed4c7-1385-4b6f-bff0-3a9d1597f342', $bp$With all his learning and discipline, he could not even see the Kingdom without new birth$bp$, $bp$Avec toute son instruction et sa discipline, il ne pouvait même pas voir le Royaume sans la nouvelle naissance$bp$, TRUE, 2),
      ('83188487-18c4-4dc4-8b81-73c7f15ca137', '416ed4c7-1385-4b6f-bff0-3a9d1597f342', $bp$With all his learning and discipline, he could enter the Kingdom, but could not lead in it$bp$, $bp$Avec toute son instruction et sa discipline, il pouvait entrer dans le Royaume, mais pas y diriger$bp$, FALSE, 3),
      ('baad7f66-ab02-46de-932e-0801ccb59067', '38195a03-948f-4716-94c0-a8e4b0487abf', $bp$A change of spiritual parentage, from the kingdom of darkness to the Kingdom of God$bp$, $bp$Un changement de filiation spirituelle, du royaume des ténèbres au Royaume de Dieu$bp$, TRUE, 0),
      ('931b7828-c5c8-435a-a5b6-73ae7955e4a9', '38195a03-948f-4716-94c0-a8e4b0487abf', $bp$A change of physical body, from a weak and sick form to a strong and healthy one$bp$, $bp$Un changement de corps physique, d'une forme faible et malade à une forme forte et en bonne santé$bp$, FALSE, 1),
      ('dcb03a9d-e6a1-4984-a152-15be5d9786b9', '38195a03-948f-4716-94c0-a8e4b0487abf', $bp$A change of church membership, from one congregation to another that teaches the keys$bp$, $bp$Un changement d'appartenance à une église, d'une congrégation à une autre qui enseigne les clés$bp$, FALSE, 2),
      ('50f3bc7b-c71e-4588-b5cd-90c9c92cdba4', '38195a03-948f-4716-94c0-a8e4b0487abf', $bp$A change of earthly nationality, from one country to another for the believer and family$bp$, $bp$Un changement de nationalité terrestre, d'un pays à un autre pour le croyant et sa famille$bp$, FALSE, 3),
      ('2ac06902-a6c6-4cea-a375-045819aa5020', 'a2c9f3f9-82f9-4777-b548-858918879432', $bp$It is protected by the church and kept safe by the prayers of other leaders in it$bp$, $bp$Elle est protégée par l'église et gardée par les prières des autres dirigeants qui s'y trouvent$bp$, FALSE, 0),
      ('223123f2-001c-4036-ac3b-1fe90285c695', 'a2c9f3f9-82f9-4777-b548-858918879432', $bp$It is sealed by the Holy Spirit and grounded in the unchanging Word, not in events$bp$, $bp$Elle est scellée par le Saint-Esprit et fondée sur la Parole immuable, et non sur les événements$bp$, TRUE, 1),
      ('09eeda2b-fca0-4103-a8d9-33ab0f4b22bc', 'a2c9f3f9-82f9-4777-b548-858918879432', $bp$It is earned by good works and kept safe by the believer's consistent obedience$bp$, $bp$Elle est gagnée par les bonnes œuvres et gardée par l'obéissance constante du croyant$bp$, FALSE, 2),
